"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[52690],{52690:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/d1dc0cb33a749e370598d3274be2fc2e.jpg\\"\\n  title=\\"신창국밥 본점\\"\\n  cuisine=\\"한식\\"\\n  address=\\"부산광역시 서구 보수대로 53\\"\\n  rating=4\\n  tags=\\"restaurant\\"\\n/>\\n</center>\\n\\n## Review\\n부산 하면 유명한 돼지국밥 맛집 중 하나인 신창국밥 본점에 방문했다.  \\n`미친 맛집`에서 소개가 되어서 어떤지 궁금하여 찾아가 보았다.  \\n\\n평일 늦은 점심시간에 방문해서 그런지 다행히 웨이팅 없이 바로 들어갈 수 있었다.  \\n\\n우리가 누가 봐도 타지에서 온 관광객 차림이라 그런지 바로 유명한 사람들이 앉았던 자리로 안내를 해주셨다.  \\n사실 우린 그런 거 별로 중요하지 않지만, 어차피 자리도 많으니 이왕이면 유명한 사람이 앉은 자리에 앉았다.  \\n\\n귀엽게도 의자마다 누가 앉았는지 이름이 붙어 있었다.  \\n나는 이재용 회장님이 앉았던 자리에 앉았다.  \\n\\n벽에는 많은 유명인들의 사인이 붙어 있었다.  \\n\\n주문한 `돼지국밥`이 바로 나왔다.  \\n토렴한 기본 돼지국밥과 `따로국밥`을 주문했는데 워낙 다 잘 먹고 막입이라 그런지 사실 큰 차이는 느끼지 못했다.  \\n둘 다 맛있었다.  \\n\\n기름지지 않고 완전 가벼운 맑은 스타일이었다.  \\n\\n호불호가 갈릴 수 있는 스타일이지만, 나는 좋았다.  \\n## Pictures\\n<pictures>\\n<img src=\\"/assets/snippets/location/91e3026c921c04cecbab277a3b3d119b.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"신창국밥 본점\\">\\n<img src=\\"/assets/snippets/location/3cb7f308748c2238223fc51f45420025.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"신창국밥 본점\\">\\n<img src=\\"/assets/snippets/location/9b1ef52293f5b418a2b7a86ede1a8419.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"신창국밥 본점\\">\\n<img src=\\"/assets/snippets/location/fc533ec6373871a78f60e442ec7fa041.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"신창국밥 본점\\">\\n</pictures>\\n"}')}}]);